SELECT\\n    fc.ITEM AS \\\"Item ID\\\",\\n    im.ITEM_DESC AS \\\"Item Description\\\",\\n    im.STATUS AS \\\"Item Status\\\",\\n    fc.DEPT AS \\\"Department Number\\\",\\n    fc.CLASS AS \\\"Class Number\\\",\\n    fc.SUBCLASS AS \\\"Subclass Number\\\",\\n    fc.SUPPLIER AS \\\"Supplier ID\\\",\\n    s.SUP_NAME AS \\\"Supplier Name\\\",\\n    fc.ORIGIN_COUNTRY_ID AS \\\"Origin Country ID\\\",\\n    fc.LOCATION AS \\\"Location ID\\\",\\n    fc.LOC_TYPE AS \\\"Location Type\\\",\\n    fc.CURRENCY_CODE AS \\\"Currency Code\\\",\\n    fc.ACTIVE_DATE AS \\\"Active Date\\\",\\n    fc.CALC_DATE AS \\\"Calculation Date\\\",\\n    fc.BASE_COST AS \\\"Base Cost\\\",\\n    fc.NET_COST AS \\\"Net Cost\\\",\\n    fc.NET_NET_COST AS \\\"Net Net Cost\\\",\\n    fc.DEAD_NET_NET_COST AS \\\"Dead Net Net Cost\\\",\\n    fc.PRICING_COST AS \\\"Pricing Cost\\\",\\n    fc.ELC_AMT AS \\\"Estimated Landed Cost Amount\\\",\\n    fc.NEGOTIATED_ITEM_COST AS \\\"Negotiated Item Cost\\\",\\n    fc.EXTENDED_BASE_COST AS \\\"Extended Base Cost\\\",\\n    fc.COST_CHANGE AS \\\"Cost Change\\\",\\n    fc.START_IND AS \\\"Start Indicator\\\",\\n    fc.SIMPLE_PACK_IND AS \\\"Simple Pack Indicator\\\",\\n    fc.PRIMARY_COST_PACK AS \\\"Primary Cost Pack\\\",\\n    fc.PRIMARY_COST_PACK_QTY AS \\\"Primary Cost Pack Quantity\\\",\\n    fc.PASSTHRU_PCT AS \\\"Passthrough Percent\\\",\\n    fc.PRIMARY_SUPP_COUNTRY_IND AS \\\"Primary Supplier Country Indicator\\\",\\n    CASE\\n        WHEN fc.COST_CHANGE &gt; 0 THEN 'Cost Increase'\\n        WHEN fc.COST_CHANGE &lt; 0 THEN 'Cost Decrease'\\n        WHEN fc.COST_CHANGE = 0 THEN 'No Change'\\n        ELSE 'Unknown'\\n    END AS \\\"Cost Change Direction\\\"\\n    FROM rds_wv_future_cost fc\\nINNER JOIN rds_wv_item_master im ON im.ITEM = fc.ITEM\\nINNER JOIN rds_wv_sups s ON s.SUPPLIER = fc.SUPPLIER\\nWHERE fc.ACTIVE_DATE &gt;= SYSDATE\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOp